package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch71 {
    val stories = listOf(
        StorySeries(
            id = "the_archive_of_small_sounds",
            title = "The Archive of Small Sounds",
            tagline = "A school audio club discovers that ordinary sounds can preserve extraordinary memories.",
            parts = listOf(
                StoryPart(1, "A Recorder in the Cupboard", listOf("The school audio club had one working microphone, three tangled cables, and a recorder nobody remembered buying. When Amadi found it in a cupboard, a label on its case read: 'Listen before you decide what matters.'", "The recorder still worked, but its memory card was empty. Their teacher suggested making a collection of sounds from around the school: the library clock, the basketball bouncing in the courtyard, and the caretaker's keys.", "Amadi wanted to record the final bell, but his friend Sola argued that everyone already knew that sound. They agreed to begin with something less obvious.")),
                StoryPart(2, "The Library Clock", listOf("The library clock made a soft click every second and a louder sound at the minute. The librarian, Mrs Danjuma, said it had been donated by a former student who wanted the room to feel welcoming.", "Amadi recorded one minute and asked why the clock mattered. Mrs Danjuma explained that students who arrived early often listened to it while waiting for the library to open.", "Sola added a note to the archive: 'A sound can mark a place where people feel safe to begin.' They decided every recording should include a short explanation from someone who knew it.")),
                StoryPart(3, "The Courtyard Rhythm", listOf("The basketball bounced in an uneven rhythm because the courtyard surface had a shallow dip. The sports teacher explained that the sound changed depending on where players stood.", "A student named Fara demonstrated the difference and described how the team had learned to pass around the uneven patch. The recording captured the ball, the shoes, and the calls between players.", "Amadi almost deleted the clip because it sounded messy. Sola reminded him that the archive was not supposed to make ordinary life sound perfect.")),
                StoryPart(4, "The Workshop Door", listOf("Behind the art room, the workshop door creaked in three distinct notes. The maintenance teacher said he had kept the old hinges because the sound reminded former students of their first projects.", "The club recorded the door opening slowly, then asked the teacher to explain which projects had been made there. He described model bridges, repaired chairs, and a school sign built by students years earlier.", "One former student heard about the recording and offered to bring photographs of the sign. The archive was beginning to connect sounds with people who had moved on.")),
                StoryPart(5, "A Voice in the Background", listOf("While reviewing a market-day recording, Sola noticed a voice in the background. It seemed to say a student's full name, followed by a phone number.", "Their teacher stopped playback and explained that recordings could capture private information by accident. They removed that section and agreed to ask permission before recording identifiable conversations.", "The club wrote a simple consent rule for the archive: record places and agreed voices, avoid private details, and let contributors review their clips before sharing.")),
                StoryPart(6, "The Old Assembly Song", listOf("A retired music teacher visited the school and recognised a melody Amadi had recorded during rehearsal. She said it was an old assembly tune that students had changed over the years.", "She brought a notebook with several versions, each marked with the year and the class that had adapted it. The club recorded her explaining the history, then asked current students to describe what the tune meant to them.", "The melody sounded different in every version, but its purpose remained: it brought people together before the school day began.")),
                StoryPart(7, "The Missing Recording", listOf("The recorder's original label suggested that an important sound had once been stored on it. The club searched the school archive and found a reference to a recording called 'Rain on the Tin Roof'.", "The file itself was missing, but a caretaker remembered the day it had been made. A heavy shower had interrupted a school performance, and students had continued singing while rain tapped above them.", "Amadi asked whether they could recreate the recording. The caretaker said they could record a new rainstorm, but they should not pretend it was the same event. The archive would preserve the memory through testimony, not a false copy.")),
                StoryPart(8, "The Listening Evening", listOf("The club prepared a listening evening in the library. Each clip played beside a photograph and a short note from its contributor.", "Visitors recognised the clock, the courtyard, and the workshop door. Some added memories, while others corrected details in the captions. The club recorded those corrections and asked permission before adding new voices.", "A former student brought a photograph of the workshop sign and identified the classmates who had built it. The sound collection had become a history project without losing its focus on listening.")),
                StoryPart(9, "The Quietest Track", listOf("The final track was nearly silent. It contained the soft rustle of pages in the library just before opening, recorded with the librarian's permission.", "At first, visitors thought the file had failed. Then Mrs Danjuma explained that the quiet was part of the sound: people settling in, choosing books, and preparing to learn.", "Amadi placed it at the end of the programme. He wanted listeners to notice that not every important moment announced itself loudly.")),
                StoryPart(10, "Keep Listening", listOf("The school created a small digital archive with clear permissions, contributor names where approved, and descriptions that could be corrected. The recorder was stored safely, but students could borrow it for new projects.", "Amadi and Sola added a final entry describing the archive itself: the click of the recorder button, the quiet before playback, and the conversations that followed each sound.", "Their teacher asked what they had learned. Amadi answered that listening was not simply collecting noise. It was paying attention, respecting the people behind a memory, and being willing to revise a story when someone offered a better account. The archive remained open for future students, ready for the next ordinary sound that deserved to be heard.")
                )
            )
        )
    )
}
